AND WFL.TRADE_ID = #{tradeId} AND WFL.WORKFLOW_STATUS = #{tradeStatus}

SELECT WFL.TRADE_ID tradeId, case WFL.TRADE_STATUS when #{validStatus_03} then #{validStatus_03} else #{validStatus_02} end tradeStatus, WFLDEAL.ENTRUST_ID entrustId, PTL.PORTFOLIO_ID portfolioId, PTL.PORTFOLIO_NAME portfolioName, WFL.FINPROD_TYPE2 finprodType, WFL.FINPROD_ID finprodIdHide, WFLDEAL.EXC_DEAL_TYPE excDealType, WFLDEAL.CUR_PAIR curPair, FINTP.EXC_PS ps, FINTP.CCY dealCur, WFL.CCY corCcy, FINTP.EXC_FXS_TERM_TYPE excFxsTermType, WFL.TRADE_DATE tradeDate, WFL.UNIT_CPRICE spotRate, WFLDEAL.TERM_TYPE nTermTypeExc, WFL.SETTLE_DATE vdate, WFL.UNIT_INT nPoint, WFL.UNIT_FPRICE nFprice, WFL.PRIN_AMT nDealCurAmt, WFL.TRADE_AMT nCorCurAmt, WFLDEAL.USD_AMT nUsdAmt, FINTP.TERM_TYPE fTermTypeExc, FINTP.MDATE mdate, FINTP.M_UNIT_INT fPoint, FINTP.M_UNIT_FPRICE fFprice, FINTP.M_PRIN_AMT fDealCurAmt, FINTP.M_TRADE_AMT fCorCurAmt, FINTP.USD_AMT fUsdAmt, WFL.REMARK remark, FINTP.CALENDAR_ID calendarId, FINTP.HOLD_PURPOSE holdPurpose, /*持有目的*/ WFLDEAL.OUR_ROLE ourRole, WFLDEAL.DEAL_MODE dealMode, WFL.DELIVERY_TYPE settMode, WFL.FEE_AMT feeAmt, WFL.COUNTER_ID CounterId, WFL.TRADER trader, WFL.COUNTER_TRADER counterTrader, WFL.COUNTER_CONTACT counterContact, null workflowId, null workflowStatus, deal2.TRADE_ID tradeId1 FROM TRD_PRODUCT_DEAL WFL LEFT JOIN TRD_PRODUCT_DEAL_ADD WFLDEAL ON WFL.TRADE_ID = WFLDEAL.TRADE_ID LEFT JOIN FIN_TRADE_PRODUCT FINTP ON WFL.FINPROD_ID = FINTP.FINPROD_ID LEFT JOIN PTL_TRADE PT ON NVL(WFL.P_TRADE_ID,WFL.TRADE_ID) = PT.BUSI_NO LEFT JOIN PTL_PORTFOLIO PTL ON PT.PORTFOLIO_ID = PTL.PORTFOLIO_ID LEFT JOIN TRD_PRODUCT_DEAL deal2 ON deal2.FINPROD_ID = WFL.FINPROD_ID and deal2.FINPROD_TYPE2 = WFL.FINPROD_TYPE2 and deal2.TRADE_STATUS = WFL.TRADE_STATUS and deal2.PS != WFL.PS
PTL.INVEST_YESORNO='Y'
