AND FINTP.EXC_FXS_TERM_TYPE IN
#{item}
AND WFL.TRADE_STATUS =#{validStatus_01} AND WFL.IS_CANCEL != 'Y'
AND WFL.TRADE_STATUS =#{validStatus_03} AND WFL.IS_CANCEL != 'Y'
AND WFL.IS_CANCEL != 'Y'
AND WFL.TRADE_DATE >= TO_DATE(#{tradeDateBegin},'YYYY-MM-DD')
AND WFL.TRADE_DATE <= TO_DATE(#{tradeDateEnd},'YYYY-MM-DD')
AND WFL.SETTLE_DATE >= TO_DATE(#{vDateBegin},'YYYY-MM-DD')
AND WFL.SETTLE_DATE <= TO_DATE(#{vDateEnd},'YYYY-MM-DD')
AND FINTP.MDATE >= TO_DATE(#{mDateBegin},'YYYY-MM-DD')
AND FINTP.MDATE <= TO_DATE(#{mDateEnd},'YYYY-MM-DD')
AND WFL.TRADE_ID = #{tradeId} AND case WFL.TRADE_STATUS when #{validStatus_03} then #{validStatus_03} else #{validStatus_02} end = #{tradeStatus}

